import unittest,re
from tools.kjv_archive import load_register,read
class RevelationWitnessPairTests(unittest.TestCase):
 def test_witness_dual_and_plural_self(self):
  prior,_=load_register('0.10-kjv.273');lang,manifest=load_register('0.10-kjv.274')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('revelation-'):c for c in read(lang.folder/'revelation-witness-pair-cases.json')};self.assertEqual(len(cases),47)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}-{'worship'}&set(r['keys']))
  anchors={'10:1': ['other mighty angel', 'cloud clothe:psv:pp', 'kjv_rainbow_revelation', 'face as sun', 'foot:pl as fire kjv_pillar:pl'], '10:2': ['little book open:psv:pp', 'kjv_right_side foot upon sea', 'left foot on earth'], '10:3': ['as when lion roar:pr', 'seven thunder:ev:pl'], '10:4': ['i write:inf about be:pa', 'seven thunder:ev:pl utter:pa seal:imp', 'write:neg:imp'], '10:5': ['upon sea and upon earth', 'his/hand to heaven lift:pa'], '10:6': ['heaven and in it thing:pl', 'earth and in it thing:pl', 'sea and in it thing:pl', 'time no longer be:should'], '10:7': ['seven:ord angel', 'god mystery finish:psv:should', 'his/servant:pl prophet:pl'], '10:8': ['again speak:pa', 'little book', 'upon sea and upon earth'], '10:9': ['little book to i give:imp', 'thy/belly bitter', 'thy/mouth sweet as honey'], '10:10': ['my/mouth sweet as honey', 'as soon as i it eat:perf my/belly bitter'], '10:11': ['he to i', 'before many people:pl and nation:pl and tongue:pl and king:pl', 'kjv_prophesy:must'], '11:1': ['reed like rod', 'angel stand:pa', 'god kjv_temple and altar and they who in it kjv_worship:pr'], '11:2': ['kjv_court_enclosure', 'measure:neg:imp', 'kjv_gentile:pl', 'forty and two month:pl'], '11:3': ['ipl to two mypl/witness:du', 'they:du thousand and two+hundred and five+twelve day:pl', 'kjv_sackcloth'], '11:4': ['two kjv_olive kjv_tree:du and two kjv_candlestick:du', 'earth god'], '11:5': ['if any man they:du:a hurt:inf will:pr', 'fire out of their/mouth', 'in this manner kill:psv:must'], '11:6': ['these:du heaven shut:inf', 'their/kjv_prophesy:ev day:pl', 'to blood turn:inf', 'all plague:pl', 'as often as they:du will:pr'], '11:7': ['they:du their/testimony finish:perf', 'kjv_bottomless_pit_revelation', 'war make:fu', 'overcome:fu', 'kill:fu'], '11:8': ['their/dead body:du', 'spirit:adv kjv_sodom and egypt', 'ourone/lord kjv_crucify:psv:pa'], '11:9': ['people and kjv_family:pl and tongue:pl and nation:pl', 'three and half day:pl', 'in grave:pl put:psv:inf permit:neg:fu'], '11:10': ['gift:pl to each other', 'two prophet:du', 'torment:pa'], '11:11': ['three and half day:pl', 'life spirit from god', 'they:du upon their/foot:pl', 'great fear'], '11:12': ['they:du great voice', 'here up come:imp', 'to heaven in cloud', 'enemy:pl they:du:a behold:pa'], '11:13': ['same hour', 'city kjv_tenth_share', 'seven+thousand', 'remainder frighten:psv:pa'], '11:14': ['second woe', 'third woe quickly'], '11:15': ['seven:ord angel', 'world kingdom:pl ourone/lord and his/kjv_christ_title kingdom:pl', 'he forever and forever rule:fu'], '11:16': ['two+twelve kjv_elder:pl', 'their/seat:pl', 'their/face:pl'], '11:17': ['wesg to thee thanks', 'be:pr and be:pa and come:fu', 'thy/great power take:perf and rule:perf'], '11:18': ['nation:pl angry', 'dead:pl time', 'thy/servant:pl prophet:pl', 'small and great', 'they who earth destroy:pr destroy:should'], '11:19': ['god kjv_temple in heaven', 'his/kjv_testament_ark_revelation kjv_ark_chest', 'lightning:pl and voice:pl and thunder:ev:pl and earthquake and great hail'], '12:1': ['woman sun clothe:psv:pp', 'moon under her/foot:pl', 'twelve star:pl crown'], '12:2': ['she pregnant', 'in birth kjv_travail:cv', 'pain:psv:pp'], '12:3': ['great red kjv_dragon_revelation', 'seven head:pl and ten horn:pl', 'seven crown:pl'], '12:4': ['star:pl kjv_third_share', 'her/child as soon as born:psv:pa devour:inf'], '12:5': ['kjv_male child', 'iron rod all nation:pl', 'to god and to his/throne'], '12:6': ['by god prepare:psv:pp place', 'they there she:a thousand and two+hundred and five+twelve day:pl feed:should'], '12:7': ['kjv_michael_revelation and his/angel:pl', 'kjv_dragon_revelation and his/angel:pl'], '12:8': ['prevail:neg:pa', 'neither their/place any more in heaven'], '12:9': ['that old serpent devil and satan', 'whole world deceive:pr', 'his/angel:pl with he'], '12:10': ['ourone/god kingdom', 'his/kjv_christ_title power', 'ourone/brother:pl accuse:ag', 'before ourone/god day and night'], '12:11': ['by kjv_lamb blood and by their/testimony word', 'their/life:pl to death love:neg:pa'], '12:12': ['earth and sea dwell:ag:pl woe:excl', 'great wrath', 'only short time'], '12:13': ['woman who kjv_male child forth bear:pa', 'persecute:pa'], '12:14': ['two great kjv_eagle wing:du', 'one_num time and time:pl and half time', 'from serpent face'], '12:15': ['water as flood after woman', 'away carry:psv:inf cause:may'], '12:16': ['earth her/mouth open:pa', 'kjv_dragon_revelation out of his/mouth', 'kjv_swallow:pa'], '12:17': ['her/kjv_seedline remainder', 'god command:pl keep:pr', 'kjv_jesus_matthew kjv_christ_title testimony']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('write:neg:imp',cases['10-4']['analysis'])
  self.assertIn('time no longer be:should',cases['10-6']['analysis'])
  self.assertIn('ipl to two mypl/witness:du',cases['11-3']['analysis'])
  self.assertIn('earth god',cases['11-4']['analysis'])
  self.assertIn('they:du great voice',cases['11-12']['analysis'])
  self.assertIn('world kingdom:pl ourone/lord and his/kjv_christ_title kingdom:pl',cases['11-15']['analysis'])
  self.assertIn('wesg to thee thanks',cases['11-17']['analysis'])
  self.assertIn('be:pr and be:pa and come:fu',cases['11-17']['analysis'])
  self.assertIn('one_num time and time:pl and half time',cases['12-14']['analysis'])
  self.assertIn('kjv_jesus_matthew kjv_christ_title testimony',cases['12-17']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),3)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
